    -- margin-composite · Margin trend composite [scope=industry]
    ('analysis.derivatives.margin-composite.margin_trend_days', 'derivatives', 'margin-composite', 'margin_trend_days', 'Trend days', 'd', 'Days in the latest margin-balance trend episode — long up-trends mean entrenched leverage (fuel for squeezes on exit), fresh trends mean new positioning.', '{"scope": "industry", "page_title": "Margin trend composite", "source": {"kind": "table", "table": "analysis.margin_changes", "value": "days_of_trend", "date": "end_date", "code": "code", "sec_type": "sec_type"}}'::jsonb, 0),
    ('analysis.derivatives.margin-composite.margin_trend_up', 'derivatives', 'margin-composite', 'margin_trend_up', 'Trend up (1/0)', '', '1 = margin balance accumulating (leveraged longs building — bullish fuel, squeeze risk on reversal); 0 = unwinding (deleveraging drag on price).', '{"scope": "industry", "rank": false, "page_title": "Margin trend composite", "source": {"kind": "table", "table": "analysis.margin_changes", "value": "is_trend_up_not_down", "date": "end_date", "code": "code", "sec_type": "sec_type"}}'::jsonb, 1),
    ('analysis.derivatives.margin-composite.index_margin_balance', 'derivatives', 'margin-composite', 'index_margin_balance', 'Margin balance', '', 'Industry aggregate margin balance (RZ cash borrow) — the stock of leveraged longs; its level and trend are the leverage context for every price move.', '{"scope": "industry", "page_title": "Margin trend composite", "source": {"kind": "table", "table": "analysis.margin_index_series", "value": "index_margin_balance", "date": "date", "code": "industry_id"}}'::jsonb, 2),
    ('analysis.derivatives.margin-composite.index_margin_buy', 'derivatives', 'margin-composite', 'index_margin_buy', 'Margin buy', '', 'Industry aggregate daily margin buy — the flow of fresh leveraged demand; surges mark conviction chases (and future forced-seller supply).', '{"scope": "industry", "page_title": "Margin trend composite", "source": {"kind": "table", "table": "analysis.margin_index_series", "value": "index_margin_buy", "date": "date", "code": "industry_id"}}'::jsonb, 3),
    ('analysis.derivatives.margin-composite.n_constituents', 'derivatives', 'margin-composite', 'n_constituents', 'Members', '', 'Constituent count behind the industry margin aggregate — thin membership discounts how far the aggregate generalizes.', '{"scope": "industry", "page_title": "Margin trend composite", "source": {"kind": "table", "table": "analysis.margin_index_series", "value": "n_constituents", "date": "date", "code": "industry_id"}}'::jsonb, 4),

