    ('analysis.derivatives.futures-price-curves.gap_ma5', 'derivatives', 'futures-price-curves', 'gap_ma5', 'Basis gap MA5', '', 'MA5-smoothed basis — the noise-free basis stance; prefer it over the raw gap for direction.', '{"scope": "security", "page_title": "Futures price curves", "source": {"kind": "table", "table": "analysis.futures_ext", "value": "gap_price_ma5_vs_underlying_ma5", "date": "date", "code": "code"}}'::jsonb, 1),
    ('analysis.derivatives.futures-price-curves.corr_price_vs_underlying', 'derivatives', 'futures-price-curves', 'corr_price_vs_underlying', '20d corr', '', '20d rolling correlation of futures vs underlying — should hug 1; a collapse (sustained well below, rare) breaks the basis-hedge premise and flags data/liquidity anomalies.', '{"scope": "security", "page_title": "Futures price curves", "source": {"kind": "table", "table": "analysis.futures_ext", "value": "corr_price_vs_underlying", "date": "date", "code": "code"}}'::jsonb, 2),

