    ('analysis.derivatives.futures-corr.corr_ma5', 'derivatives', 'futures-corr', 'corr_ma5', '20d corr (MA5)', '', 'The same 20d correlation on MA5-smoothed series — the smoothed twin; raw-vs-smoothed divergence localizes whether noise or a real regime broke the link.', '{"scope": "security", "page_title": "Futures vs underlying correlation", "source": {"kind": "table", "table": "analysis.futures_ext", "value": "corr_price_ma5_vs_underlying_ma5", "date": "date", "code": "code"}}'::jsonb, 1),

